<?php
require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php';
$page_title='My Timetable'; $user=$_SESSION['username'];
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];
$hours=[1=>['09:00','10:00'],2=>['10:15','11:15'],3=>['11:15','12:15'],4=>['13:45','14:45'],5=>['15:00','16:00']];
$st=$conn->prepare("SELECT tt.*,b.batch_name,b.course FROM tbl_timetable tt JOIN tbl_batches b ON b.id=tt.batch_id WHERE tt.teacher_username=? ORDER BY tt.semester,tt.day_of_week,tt.hour_no");$st->bind_param('s',$user);$st->execute();$r=$st->get_result();$grid=[];while($x=$r->fetch_assoc())$grid[$x['semester']][$x['day_of_week']][$x['hour_no']]=$x;
$semesters=array_keys($grid); sort($semesters);
require '../includes/header.php';
?>
<div class="glass-hero mb-4"><div><span class="eyebrow-dark">MY SCHEDULE</span><h2>Teaching timetable</h2><p>Your classes are assigned by the administrator. These are the only hours available for hourly attendance.</p></div><div class="hero-orb"><i class="fa-solid fa-calendar-week"></i></div></div>
<div class="hour-strip glass-card mb-4"><div><strong>College day</strong><span class="small-muted">Fixed five-hour schedule</span></div><div class="hour-chip"><b>H1</b> 09:00–10:00</div><div class="break-chip">10:00–10:15 break</div><div class="hour-chip"><b>H2</b> 10:15–11:15</div><div class="hour-chip"><b>H3</b> 11:15–12:15</div><div class="break-chip">12:15–13:45 lunch</div><div class="hour-chip"><b>H4</b> 13:45–14:45</div><div class="break-chip">14:45–15:00 break</div><div class="hour-chip"><b>H5</b> 15:00–16:00</div></div>
<div class="glass-card"><div class="d-flex justify-content-between align-items-center"><div><div class="section-kicker">WEEKLY VIEW</div><h5>All assigned classes</h5></div><span class="badge badge-soft">5 hours / day</span></div><?php if(!$semesters):?><div class="empty mt-4">No timetable assignments yet.</div><?php endif;?><?php foreach($semesters as $semNo):?><div class="semester-view-block mt-4"><div class="semester-view-title"><strong>Semester <?php echo (int)$semNo;?></strong><span class="small-muted">Year <?php echo (int)ceil($semNo/2);?></span></div><div class="timetable-wrap mt-3"><table class="table timetable-table modern-timetable"><thead><tr><th>Day</th><?php foreach($hours as $h=>$time): ?><th><span>Hour <?php echo $h; ?></span><small><?php echo $time[0].'–'.$time[1]; ?></small></th><?php endforeach; ?></tr></thead><tbody><?php foreach($days as $dn=>$day): ?><tr><th><?php echo $day; ?></th><?php for($h=1;$h<=5;$h++):$s=$grid[$semNo][$dn][$h]??null; ?><td><?php if($s): ?><div class="tt-cell"><span class="tt-hour">H<?php echo $h; ?></span><strong><?php echo e($s['subject']); ?></strong><span><?php echo e($s['batch_name']); ?></span><small><?php echo e(substr($s['start_time'],0,5)); ?>–<?php echo e(substr($s['end_time'],0,5)); ?></small></div><?php else: ?><span class="tt-empty">No class</span><?php endif; ?></td><?php endfor; ?></tr><?php endforeach; ?></tbody></table></div></div><?php endforeach;?></div>
<?php require '../includes/footer.php'; ?>
